<?php
 namespace App\Http\Controllers; use Illuminate\Http\Request; use App\Http\Requests\ProjectRequest; use App\Models\Project; class ProjectController extends Controller { public function index() { $projects = Project::withCount(['lots as available' => function ($q) { $q->where('status', 'available'); }])->get(); return view('projects.index', compact('projects')); } public function create() { return view('projects.create'); } public function store(ProjectRequest $request) { Project::create($request->validated()); return redirect()->route('projects.index')->with('success', 'Project ditambahkan'); } public function edit(Project $project) { return view('projects.edit', compact('project')); } public function update(ProjectRequest $request, Project $project) { $project->update($request->validated()); return redirect()->route('projects.index')->with('success', 'Project diperbarui'); } public function destroy(Project $project) { $project->delete(); return redirect()->route('projects.index')->with('success', 'Project dihapus'); } } 